Add-Type -AssemblyName System.Windows.FormsAdd-Type -AssemblyName System.Drawing# ------------------------------------------------------------# Windows power-management helper# ------------------------------------------------------------Add-Type @"using System;using System.Runtime.InteropServices;public static class SleepControl{    private const uint ES_CONTINUOUS       = 0x80000000;    private const uint ES_SYSTEM_REQUIRED  = 0x00000001;    private const uint ES_DISPLAY_REQUIRED = 0x00000002;    [DllImport("kernel32.dll", SetLastError = true)]    private static extern uint SetThreadExecutionState(uint esFlags);    public static bool Enable()    {        uint result = SetThreadExecutionState(            ES_CONTINUOUS |            ES_SYSTEM_REQUIRED |            ES_DISPLAY_REQUIRED        );        return result != 0;    }    public static void Disable()    {        SetThreadExecutionState(ES_CONTINUOUS);    }}"@# Obtain the helper methods through reflection.# This avoids PowerShell parsing issues with static constants.$sleepControlType = New-Object System.Type[] 0$sleepControlType = [SleepControl]$enableMethod = $sleepControlType.GetMethod("Enable")$disableMethod = $sleepControlType.GetMethod("Disable")# ------------------------------------------------------------# Logging# ------------------------------------------------------------$logFile = Join-Path $env:TEMP "keepawake.log"function Write-Log {    param(        [Parameter(Mandatory = $true)]        [string]$Message    )    $logEntry = "{0} - {1}" -f `        (Get-Date -Format "yyyy-MM-dd HH:mm:ss"),        $Message    $logEntry |        Out-File `            -FilePath $logFile `            -Append `            -Encoding utf8}function Enable-KeepAwake {    $result = $enableMethod.Invoke($null, $null)    if (-not $result) {        throw "Windows could not enable keep-awake mode."    }}function Disable-KeepAwake {    try {        $disableMethod.Invoke($null, $null) | Out-Null    }    catch {        Write-Log "Warning: Could not restore normal sleep mode: $($_.Exception.Message)"    }}# ------------------------------------------------------------# Main application window# ------------------------------------------------------------$form = New-Object System.Windows.Forms.Form$form.Text = "Sleeper"$form.ClientSize = New-Object System.Drawing.Size(420, 250)$form.StartPosition = "CenterScreen"$form.FormBorderStyle = "FixedDialog"$form.MaximizeBox = $false$form.MinimizeBox = $true$form.BackColor = [System.Drawing.Color]::FromArgb(31, 35, 43)$form.ForeColor = [System.Drawing.Color]::White$form.TopMost = $false# ------------------------------------------------------------# Application title# ------------------------------------------------------------$title = New-Object System.Windows.Forms.Label$title.Text = "SLEEPER"$title.Font = New-Object System.Drawing.Font(    "Segoe UI",    22,    [System.Drawing.FontStyle]::Bold)$title.AutoSize = $true$title.Location = New-Object System.Drawing.Point(135, 30)$title.ForeColor = [System.Drawing.Color]::FromArgb(80, 200, 255)$form.Controls.Add($title)# ------------------------------------------------------------# Status indicator# ------------------------------------------------------------$statusDot = New-Object System.Windows.Forms.Label$statusDot.Text = [char]0x25CF$statusDot.Font = New-Object System.Drawing.Font("Segoe UI", 18)$statusDot.AutoSize = $true$statusDot.Location = New-Object System.Drawing.Point(87, 90)$statusDot.ForeColor = [System.Drawing.Color]::Orange$form.Controls.Add($statusDot)# ------------------------------------------------------------# Status message# ------------------------------------------------------------$statusLabel = New-Object System.Windows.Forms.Label$statusLabel.Text = "Starting keep-awake mode..."$statusLabel.Font = New-Object System.Drawing.Font("Segoe UI", 12)$statusLabel.AutoSize = $true$statusLabel.Location = New-Object System.Drawing.Point(125, 96)$statusLabel.ForeColor = [System.Drawing.Color]::White$form.Controls.Add($statusLabel)# ------------------------------------------------------------# Running-time display# ------------------------------------------------------------$runtimeLabel = New-Object System.Windows.Forms.Label$runtimeLabel.Text = "Running time: 00:00:00"$runtimeLabel.Font = New-Object System.Drawing.Font("Segoe UI", 10)$runtimeLabel.AutoSize = $true$runtimeLabel.Location = New-Object System.Drawing.Point(127, 140)$runtimeLabel.ForeColor = [System.Drawing.Color]::LightGray$form.Controls.Add($runtimeLabel)# ------------------------------------------------------------# Stop button# ------------------------------------------------------------$stopButton = New-Object System.Windows.Forms.Button$stopButton.Text = "Stop and close"$stopButton.Size = New-Object System.Drawing.Size(150, 40)$stopButton.Location = New-Object System.Drawing.Point(135, 185)$stopButton.FlatStyle = "Flat"$stopButton.FlatAppearance.BorderSize = 0$stopButton.BackColor = [System.Drawing.Color]::FromArgb(200, 70, 70)$stopButton.ForeColor = [System.Drawing.Color]::White$stopButton.Font = New-Object System.Drawing.Font(    "Segoe UI",    10,    [System.Drawing.FontStyle]::Bold)$stopButton.Cursor = [System.Windows.Forms.Cursors]::Hand$form.Controls.Add($stopButton)# ------------------------------------------------------------# Runtime timer# ------------------------------------------------------------$script:startTime = Get-Date$script:keepAwakeEnabled = $false$script:cleanupCompleted = $false$timer = New-Object System.Windows.Forms.Timer$timer.Interval = 1000$timer.Add_Tick({    $elapsed = (Get-Date) - $script:startTime    # Include complete days in the displayed hour count    $totalHours = ($elapsed.Days * 24) + $elapsed.Hours    $runtimeLabel.Text = "Running time: {0:00}:{1:00}:{2:00}" -f `        $totalHours,        $elapsed.Minutes,        $elapsed.Seconds})# ------------------------------------------------------------# Cleanup function# ------------------------------------------------------------function Stop-Sleeper {    if ($script:cleanupCompleted) {        return    }    $script:cleanupCompleted = $true    if ($null -ne $timer) {        $timer.Stop()    }    if ($script:keepAwakeEnabled) {        Disable-KeepAwake        $script:keepAwakeEnabled = $false    }    Write-Log "Sleeper stopped"}# ------------------------------------------------------------# Button and window events# ------------------------------------------------------------$stopButton.Add_Click({    $form.Close()})$form.Add_Shown({    try {        Enable-KeepAwake        $script:keepAwakeEnabled = $true        $script:startTime = Get-Date        $statusDot.ForeColor = [System.Drawing.Color]::LimeGreen        $statusLabel.Text = "Keep-awake mode is active"        Write-Log "Sleeper started"        $timer.Start()    }    catch {        $statusDot.ForeColor = [System.Drawing.Color]::Red        $statusLabel.Text = "Could not enable keep-awake mode"        $stopButton.Text = "Close"        Write-Log "ERROR: $($_.Exception.Message)"        [System.Windows.Forms.MessageBox]::Show(            $_.Exception.Message,            "Sleeper error",            [System.Windows.Forms.MessageBoxButtons]::OK,            [System.Windows.Forms.MessageBoxIcon]::Error        ) | Out-Null    }})$form.Add_FormClosing({    Stop-Sleeper})# ------------------------------------------------------------# Start application# ------------------------------------------------------------try {    [void]$form.ShowDialog()}catch {    Write-Log "Unexpected error: $($_.Exception.Message)"    [System.Windows.Forms.MessageBox]::Show(        $_.Exception.Message,        "Sleeper error",        [System.Windows.Forms.MessageBoxButtons]::OK,        [System.Windows.Forms.MessageBoxIcon]::Error    ) | Out-Null}finally {    Stop-Sleeper    if ($null -ne $timer) {        $timer.Dispose()    }    if ($null -ne $form) {        $form.Dispose()    }}